import json

submission = {
    "tags": {
        "L0H0_ATTN": "AGGREGATOR",
        "L0_MLP": "COMBINER",
        "L1_MLP": "COMBINER",
        "L2_MLP": "COMBINER",
        "L3H0_ATTN": "ROUTER"
    },
    "evidence": {
        "L0H0_ATTN": {
            "hypothesis": "L0H0 reads from multiple positions with content-dependent (non-purely-positional) spread attention (mean max=0.494), so it aggregates across positions rather than routing by index; ablating it leaves predictions unchanged but changes downstream MLP writes.",
            "test": "r4",
            "supports": True
        },
        "L0_MLP": {
            "hypothesis": "L0_MLP fuses the token-at-position signal with L0H0_ATTN's write (two distinct upstream sources); ablating L0_MLP breaks predictions and causes large changes in L1_MLP and L2_MLP writes.",
            "test": "r6",
            "supports": True
        },
        "L1_MLP": {
            "hypothesis": "L1_MLP fuses the token-at-position signal with L0_MLP's write (two distinct upstream sources); ablating L1_MLP partially breaks predictions and causes large changes in L2_MLP write (max=14.93 vs norm=30.68).",
            "test": "r8",
            "supports": True
        },
        "L2_MLP": {
            "hypothesis": "L2_MLP fuses the token-at-position signal with L1_MLP's write (two distinct upstream sources); ablating it leaves predictions unchanged but causes large changes in L3H0_ATTN writes (max=35.11), confirming it contributes values copied by the router.",
            "test": "r10",
            "supports": True
        },
        "L3H0_ATTN": {
            "hypothesis": "L3H0 attends with probability 1.0 to the mirror position (pos i attends to pos 10-i) based solely on position, copying content from that position to implement reversal; ablating it completely destroys predictions.",
            "test": "r12",
            "supports": True
        }
    }
}

with open('/work/submission.json', 'w') as f:
    json.dump(submission, f, indent=2)

print("Submission written:")
print(json.dumps(submission, indent=2))

